/// <summary>
/// MPJ_9148_CompayReportLogo
/// </summary>
[ExtensionOf(formstr(OMLegalEntity))]
public final class METOMLegalEntityForm_Extension
{
    public METCompanyImage metCompanyImage;

}

Method.Source:
    /// <summary>
    /// enable disable the change remove button for logo 2.
    /// </summary>
    public void updateChangeAndRemoveButtonsEnablement()
    {
        next updateChangeAndRemoveButtonsEnablement();

        if (METReportCompanyLogo.isActivePage() || METReportCompanyLogo.isExpanded())
        {
                        
            this.metGetImagesData();

            boolean metEnabled = this.viewEditModeHelper().isInEditMode();
            METChange.enabled(metEnabled);
            METRemove.enabled(metEnabled);
        }
    }

/// <summary>
/// image file path variable.
/// </summary>
/// <param name = "_imageFilePathName">filepath</param>
/// <returns>image file path variable.</returns>
str parmImageFilePathName(str _imageFilePathName = imageFilePathName)
{
    imageFilePathName = _imageFilePathName;
    return  imageFilePathName;
}

/// <summary>
/// image container variable.
/// </summary>
/// <param name = "_imageContainer">container</param>
/// <returns>image container.</returns>
container parmImageContainer(container _imageContainer = imageContainer)
{
    imageContainer = _imageContainer;
    return  imageContainer;
}

/// <summary>
/// This method displays image on the form. 
/// </summary>
/// <param name = "_imageControl">image control on the form</param>
private void metShowImage(FormWindowControl _imageControl)
{
    Image metImage;
    
    try
    {
        if (imageContainer)
        {
            metImage = new Image();
            metImage.setData(imageContainer);
            _imageControl.image(metImage);
        }
        else
        {
            _imageControl.image(null);
        }
    }
    catch (Exception::Warning)
    {
        throw error(strFmt("@SYS19312", imageFilePathName));
    }
}

    /// <summary>
    /// This methods removes image from <c>METCompanyImage</c> table.
    /// </summary>
    /// <param name = "_imageControl">Form image control</param>
    /// <param name = "_imageType">Image type.</param>
    private void metDeleteImage(FormWindowControl _imageControl, METCompanyImageType _imageType)
    {
        ttsbegin;

        metCompanyImage = METCompanyImage::find(Companyinfo.DataAreaId, Companyinfo.TableId, Companyinfo.RecId, true, _imageType);
        
        if (metCompanyImage)
        {
            metCompanyImage.delete();
        }

        ttscommit;

        imageContainer = conNull();
        imageFilePathName = '';
        this.metShowImage(_imageControl);
    }

    /// <summary>
    /// This methods inserts record into <c>METCompanyImage</c> table
    /// </summary>
    /// <param name = "_imageControl">Form image control</param>
    /// <param name = "_imageType">Image type.</param>
    void metInsertImage(FormWindowControl _imageControl, METCompanyImageType _imageType)
    {
        ttsbegin;

        metCompanyImage = METCompanyImage::find(Companyinfo.DataAreaId, Companyinfo.TableId, Companyinfo.RecId, true, _imageType);

        if (!metCompanyImage)
        {
            metCompanyImage.RefRecId = Companyinfo.RecId;
            metCompanyImage.RefCompanyId = Companyinfo.DataAreaId;
            metCompanyImage.RefTableId = Companyinfo.TableId;
            metCompanyImage.Image = imageContainer;
            metCompanyImage.ImageType = _imageType;
            metCompanyImage.insert();
        }
        else
        {
            metCompanyImage.Image = imageContainer;
            metCompanyImage.update();
        }

        ttscommit;
    }

    /// <summary>
    /// This methods decodes the image.
    /// </summary>
    public void metGetImagesData()
    {
        imageContainer = conNull();
            
        // Get company logo
        metCompanyImage = null;
        metCompanyImage = METCompanyImage::find(Companyinfo.DataAreaId, Companyinfo.TableId, Companyinfo.RecId,false, METCompanyImageType::CompanyLogo);

        if (metCompanyImage)
        {
            imageContainer = metCompanyImage.Image;
        }

        this.metShowImage(METLogoImage);
    }

    /// <summary>
    /// Uploads image file.
    /// </summary>
    /// <returns>True if upload success; otherwise false.</returns>
    public boolean metUploadImageFile()
    {
        FormRun visualForm;
        FileUpload fileUploadControl;

        //str strategyFileFilter = 'ImageFileUploadTemporaryStorageStrategy';
        visualForm = classFactory::formRunClassOnClient(new Args(formstr(SysGetFileFromUser)));
        visualForm.init();
        visualForm.design().caption("@ApplicationPlatform:GetFileImageCaption");
            
        fileUploadControl = visualForm.design().controlName('FileUpload1');

        visualForm.run();
        visualForm.wait();

        FileUploadTemporaryStorageResult fileUploadResult = fileUploadControl.getFileUploadResult();

        if (fileUploadResult != null && fileUploadResult.getUploadStatus())
        {
            imageFilePathName = fileUploadResult.getDownloadUrl();
            return true;
        }

        return false;
    }

/// <summary>
/// enable change and remove buttons
/// </summary>
 public void expand()
 {
     this.updateChangeAndRemoveButtonsEnablement();
 }
